#define PIN_SPARK 9             // Пин для управления катушкой зажигания
#define RPM_SENSOR_PIN 2        // Пин для датчика оборотов
#define MAX_RPM 6000            // Максимальные обороты

volatile int pulseCount = 0;    // Счетчик импульсов
unsigned long lastTime = 0;      // Время последнего измерения
int rpm = 0;                     // Обороты в минуту
int ignitionDelay = 0;           // Задержка зажигания

// Таблица углов опережения зажигания в зависимости от RPM
int uozByRpm[7][10] = {
    {5, 10, 15, 20, 25, 30, 35, 40, 45, 50}, // RPM: [0-999]
    {5, 10, 15, 20, 25, 30, 35, 40, 45, 50}, // RPM: [1000-1999]
    {5, 10, 15, 20, 25, 30, 35, 40, 45, 50}, // RPM: [2000-2999]
    {5, 10, 15, 20, 25, 30, 35, 40, 45, 50}, // RPM: [3000-3999]
    {5, 10, 15, 20, 25, 30, 35, 40, 45, 50}, // RPM: [4000-4999]
    {5, 10, 15, 20, 25, 30, 35, 40, 45, 50}, // RPM: [5000-5999]
    {5, -1,-1,-1,-1,-1,-1,-1,-1,-1}          // RPM: [6000+]
};

void setup() {
    pinMode(PIN_SPARK, OUTPUT);
    pinMode(RPM_SENSOR_PIN, INPUT_PULLUP);
    attachInterrupt(digitalPinToInterrupt(RPM_SENSOR_PIN), countPulse, RISING);
    Serial.begin(9600);
}

void loop() {
    unsigned long currentTime = millis();
    
    if (currentTime - lastTime >= 1000) {
        rpm = pulseCount * 60; // Умножаем на 60 для перевода в минуты
        pulseCount = 0;        // Сбрасываем счетчик
        lastTime = currentTime;

        if (rpm < MAX_RPM) {
            int x = rpm / (1000); // Вычисляем строку массива с углами
            int y = (rpm % (1000)) / (100); // Вычисляем столбец массива с углами
            
            if (y < sizeof(uozByRpm[x])/sizeof(uozByRpm[x][0])) {
                ignitionDelay = calculateIgnitionDelay(uozByRpm[x][y], rpm);
                triggerIgnition(ignitionDelay);
            }
        }
    }
}

void countPulse() {
    pulseCount++;
}

int calculateIgnitionDelay(int ignitionAngleDegrees, int currentRpm) {
    float timePerDegree = (60.0 / currentRpm) / (360.0); // Время на один градус
    return (ignitionAngleDegrees * timePerDegree) * 1000000; // Время в микросекундах
}

void triggerIgnition(int delayMs) {
    digitalWrite(PIN_SPARK,HIGH);   // Включить катушку
    delayMicroseconds(delayMs);      // Задержка для момента зажигания
    digitalWrite(PIN_SPARK,LOW);     // Выключить катушку

    Serial.print("RPM: ");
    Serial.print(rpm);
    Serial.print(" | Ignition Delay: ");
    Serial.println(delayMs);
}
